///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        fn_GetParentValue();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_outdir",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_outdir=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        $c.stf.doLogSave('ULDSTF39003.xml', SCREN_PROCS_TP_CD_01);
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);

        // fn_Init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39002.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    rdo_mkt_tp_cd.setValue(js_market);
    if (js_market === "9") {
        rdo_mkt_tp_cd.setDisabled(false);
        rdo_mkt_tp_cd.addClass("TopCondition_Blue");
    } else {
        // 콘트롤 잠그기
        // grd_Grid.ColumnProp("MKT_NM", "Show") = false;
        rdo_mkt_tp_cd.setDisabled(true);
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_outdir_OnSuccess
 * @description outdir On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_outdir_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 처리 되었습니다.");
        await $c.win.closePopup();
        // 부모창 reload 처리해야함
        $c.frame.path("../").fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39002.trs_outdir_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_outdir_OnFail
 * @description outdir On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_outdir_OnFail = async function() {
    try {
        await $c.win.alert('trs_outdir.OnFail() :' + trs_outdir.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39002.trs_outdir_OnFail" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39002.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.insert();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39002.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39002.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39002.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39002.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39002.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39002.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39002.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39002.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39002.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39002.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39002.Grd_com_isur_OnKillFocus" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name insert
 * @description insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    if (txb_com_abbrv.getValue() === "" || txb_com_abbrv.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "법인코드(명)"));
        txb_isur_cd.focus();
        return;
    }
    if (txb_outdir_nm.getValue() === "" || txb_outdir_nm.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "사외이사명"));
        txb_outdir_nm.focus();
        return;
    }
    // alert(Number(getObjectValue(edt_encryp_birthdd)));
    // alert(getObjectValue(edt_encryp_birthdd));
    // alert(edt_encryp_birthdd.value);

    if (edt_encryp_birthdd.getValue() !== "") {
        if (Number(edt_encryp_birthdd.getValue()) > $c.ut.cGetToday("yyyymmdd").substring(0, 4)) {
            await $c.win.alert("현재 연도보다 출생 연도가 큽니다.");
            edt_encryp_birthdd.focus();
            return;
        }
        if (edt_encryp_birthdd.getValue().length < 4) {
            await $c.win.alert("출생연도는 4자리 입니다.");
            edt_encryp_birthdd.focus();
            return;
        }
    }
    dts_outdir.insertRow();
    // dts_outdir.NameValue(1,"MKT_TP_CD") = getObjectValue(rdo_mkt_tp_cd);
    dts_outdir.setCellData(1, "ISUR_CD", txb_isur_cd.getValue());
    dts_outdir.setCellData(1, "OUTDIR_NM", txb_outdir_nm.getValue());
    dts_outdir.setCellData(1, "ENCRYP_BIRTHDD", edt_encryp_birthdd.getValue());
    const vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer === true) {
        trs_outdir.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_outdir",
            action : "/OutDir.do",
            ref : "dts_outdir",
            target : "trs_outdir=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};
